/**
 * The shipped catalog, loaded from generated JSON. Import this from the
 * `./data` subpath so core users do not pay for it:
 *
 * ```ts
 * import { cards, sets, catalogVersion } from "@dierkens.dev/ptcg-decklist-tools/data";
 * ```
 *
 * The JSON is generated by `pnpm run catalog` from a pinned public TCGdex dump.
 * It is validated there; this module only gives it the public types.
 */

import archetypesJson from "./data/archetypes.json" with { type: "json" };
import cardsJson from "./data/cards.json" with { type: "json" };
import setsJson from "./data/sets.json" with { type: "json" };
import versionJson from "./data/version.json" with { type: "json" };

import type { CatalogArchetype, CatalogCard, CatalogSet } from "./types.js";

export type { CatalogArchetype, CatalogCard, CatalogSet } from "./types.js";

/** The build date of this catalog, `YYYY-MM-DD`. Store it beside a hash. */
export const catalogVersion: string = versionJson.version;

/** Every set, oldest first. */
export const sets: readonly CatalogSet[] = setsJson as readonly CatalogSet[];

/** Every Live-addressable printing, in set and collector-number order. */
export const cards: readonly CatalogCard[] = cardsJson as readonly CatalogCard[];

/** Window-scoped Limitless archetype aliases. */
export const archetypes: readonly CatalogArchetype[] =
  archetypesJson as readonly CatalogArchetype[];
